<script setup lang="ts">
import {reactive,ref} from 'vue'
import {HysForm,HysFormItem,HysInput,HysNumberInput,HysButton,type HysFormRules} from 'hys-ui'
const model=reactive({name:'',email:'',age:16}),message=ref('')
const rules:HysFormRules={name:[{required:true,whitespace:true,message:'姓名不能只包含空白字符'},{min:2,max:20,message:'姓名长度为 2–20 个字符'}],email:[{required:true,message:'请输入邮箱'},{type:'email',message:'邮箱格式不正确'}],age:{type:'integer',min:18,max:100,message:'请输入 18–100 之间的整数'}}
</script>
<template><div class="demo-content"><HysForm :model="model" :rules="rules" label-position="left" @submit="message='规则校验成功'"><HysFormItem label="姓名" prop="name" feedback-icon><HysInput v-model="model.name"/></HysFormItem><HysFormItem label="邮箱" prop="email" feedback-icon><HysInput v-model="model.email"/></HysFormItem><HysFormItem label="年龄" prop="age" feedback-icon><HysNumberInput v-model="model.age" :min="0" :max="120"/></HysFormItem><template #actions="{validating}"><HysButton type="submit" :loading="validating">检查规则</HysButton><HysButton type="reset" variant="secondary">恢复初始值</HysButton></template></HysForm><output class="state-output">{{message||'支持类型、范围、长度、枚举、正则、空白字符和自定义规则。'}}</output></div></template>